import{_ as s,o as n,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Klassifizierung und Symbiose fremder Rassen","description":"","frontmatter":{},"headers":[],"relativePath":"de/52-异族分类与共生.md","filePath":"de/52-异族分类与共生.md","lastUpdated":null}'),t={name:"de/52-异族分类与共生.md"};function a(d,e,l,u,o,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="klassifizierung-und-symbiose-fremder-rassen" tabindex="-1">Klassifizierung und Symbiose fremder Rassen <a class="header-anchor" href="#klassifizierung-und-symbiose-fremder-rassen" aria-label="Permalink to &quot;Klassifizierung und Symbiose fremder Rassen&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Punkt</th><th>Inhalt</th></tr></thead><tbody><tr><td>Dokumentennummer</td><td>52</td></tr><tr><td>Modul</td><td>Rassen und Lebensformen</td></tr><tr><td>Kernschlüsselwörter</td><td>Fremde Rassen, Klassifizierungskriterien, Symbiosemodi, kultureller Respekt, rassische Anpassung</td></tr></tbody></table><h2 id="i-definition-des-konzepts-fremder-rassen" tabindex="-1">I. Definition des Konzepts fremder Rassen <a class="header-anchor" href="#i-definition-des-konzepts-fremder-rassen" aria-label="Permalink to &quot;I. Definition des Konzepts fremder Rassen&quot;">​</a></h2><p>Im Kontext der Anker-Symbiose-Zivilisation ist &quot;fremde Rassen&quot; ein Konzept, das relativ zur Menschenrasse ist und sich auf alle Rassen außer der Menschenrasse bezieht. Es ist besonders wichtig zu betonen, dass das Konzept der &quot;fremden Rassen&quot; nur taxonomische Bedeutung hat und keinerlei Werturteil oder diskriminierende Bedeutung trägt. Im Rahmen der Symbiose-Verfassung genießen fremde Rassen und die Menschenrasse einen vollständig gleichen Rechtsstatus und gleiche Grundrechte.</p><p>Der Zweck der Einführung des Konzepts fremder Rassen besteht darin, die verschiedenen Lebensformen außerhalb der Menschenrasse systematisch zu verstehen und zu erforschen, und eine wissenschaftliche Grundlage für die Formulierung gezielter Symbiosepolitiken, kultureller Schutzmaßnahmen und rassischer Anpassungspläne zu liefern, anstatt fremde Rassen als &quot;die Anderen&quot; oder &quot;die Fremden&quot; zu behandeln.</p><h2 id="ii-klassifizierungskriterien-fremder-rassen" tabindex="-1">II. Klassifizierungskriterien fremder Rassen <a class="header-anchor" href="#ii-klassifizierungskriterien-fremder-rassen" aria-label="Permalink to &quot;II. Klassifizierungskriterien fremder Rassen&quot;">​</a></h2><p>Die fremden Rassen von Hengyuanzhou werden nach mehreren Dimensionen klassifiziert und bilden ein multidimensionales Klassifizierungssystem:</p><h3 id="a-nach-lebensabstammung" tabindex="-1">(A) Nach Lebensabstammung <a class="header-anchor" href="#a-nach-lebensabstammung" aria-label="Permalink to &quot;(A) Nach Lebensabstammung&quot;">​</a></h3><p>Dies ist das grundlegendste Klassifizierungskriterium, Einzelheiten siehe 《50-Übersicht über die Genealogie aller Rassen》:</p><table tabindex="0"><thead><tr><th>Abstammung</th><th>Enthaltene fremde Rassen</th></tr></thead><tbody><tr><td>Kohlenstoffbasierte Materie-Rasse</td><td>Tierrasse, Schuppenrasse, Gefiederte Rasse, Baumrasse usw.</td></tr><tr><td>Energie-kondensierte Rasse</td><td>Geisterrasse, Feuerrasse, Wasserrasse, Windrasse, Donnerrasse usw.</td></tr><tr><td>Mechanische Konstruktionsrasse</td><td>Maschinenrasse, Zahlenrasse, Kristallrasse usw.</td></tr><tr><td>Bewusstseins-Informationsrasse</td><td>Traumrasse, Schattenrasse, Gedankenrasse, Seelenrasse usw.</td></tr><tr><td>Gemischte Mutationsrasse</td><td>Halb-Tierrasse, Dämon-Geisterrasse, Mensch-Maschine-Rasse, Doppel-Seelen-Körper usw.</td></tr></tbody></table><h3 id="b-nach-zivilisationsgrad" tabindex="-1">(B) Nach Zivilisationsgrad <a class="header-anchor" href="#b-nach-zivilisationsgrad" aria-label="Permalink to &quot;(B) Nach Zivilisationsgrad&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ebene</th><th>Name</th><th>Merkmale</th><th>Repräsentative Rassen</th></tr></thead><tbody><tr><td>Erste Ebene</td><td>Primitiv-Zivilisationsrasse</td><td>Hat noch kein stabiles Sozialsystem etabliert, überlebt in Stammesform</td><td>Einige Zweige der Tierrasse, primitive Baumrasse</td></tr><tr><td>Zweite Ebene</td><td>Klassisch-Zivilisationsrasse</td><td>Hat Staatssystem und klassische Kultur etabliert, befindet sich in Agrar- oder Handwerksstufe</td><td>Einige Schuppenrassen, Gefiederte Rassen</td></tr><tr><td>Dritte Ebene</td><td>Techno-Zivilisationsrasse</td><td>Hat techno-Zivilisation entwickelt, ist in Industrie- oder Informationszeitalter eingetreten</td><td>Maschinenrasse, Zahlenrasse, einige Menschenrassen</td></tr><tr><td>Vierte Ebene</td><td>Kultivierungs-Zivilisationsrasse</td><td>Verwendet Kultivierungssystem als zentrale Zivilisationsform, Kultivierende dominieren in der Gesellschaft</td><td>Geisterrasse, Drachenrasse, einige Menschenrassen</td></tr><tr><td>Fünfte Ebene</td><td>Symbiose-Zivilisationsrasse</td><td>Ist bereits der Anker-Symbiose-Zivilisation beigetreten, akzeptiert Symbiose-Ideale und -Institutionen</td><td>Alle Rassen, die der Symbiose-Zivilisation beigetreten sind</td></tr></tbody></table><h3 id="c-nach-umweltanpassung" tabindex="-1">(C) Nach Umweltanpassung <a class="header-anchor" href="#c-nach-umweltanpassung" aria-label="Permalink to &quot;(C) Nach Umweltanpassung&quot;">​</a></h3><ul><li><strong>Landrasse</strong>: Rassen, die an die Landumgebung angepasst sind, wie die Menschenrasse, die Tierrasse, die Maschinenrasse.</li><li><strong>Wasserrasse</strong>: Rassen, die an die Wasserumgebung angepasst sind, wie die Schuppenrasse, die Wasserrasse, einige gemischte Rassen.</li><li><strong>Luftrasse</strong>: Rassen, die an die Hochgebirgs- oder Flugumgebung angepasst sind, wie die Gefiederte Rasse, die Windrasse.</li><li><strong>Feuerrasse</strong>: Rassen, die an die Hochtemperaturumgebung angepasst sind, wie die Feuerrasse, einige Schuppenrassen.</li><li><strong>Eisrasse</strong>: Rassen, die an die Niedrigtemperaturumgebung angepasst sind, wie die Eisrasse, einige Baumrassen.</li><li><strong>Energierasse</strong>: Rassen, die an die Umgebung mit hoher Energiekonzentration angepasst sind, wie die Geisterrasse, die Donnerrasse.</li><li><strong>Raumrasse</strong>: Rassen, die an die Umgebung von Raumspalten oder fremden Räumen angepasst sind, wie die Schattenrasse, einige Gedankenrassen.</li></ul><h3 id="d-nach-sozialform" tabindex="-1">(D) Nach Sozialform <a class="header-anchor" href="#d-nach-sozialform" aria-label="Permalink to &quot;(D) Nach Sozialform&quot;">​</a></h3><ul><li><strong>Individualistische Rasse</strong>: Betont individuelle Unabhängigkeit und Freiheit, lockere Sozialstruktur, wie einige Geisterrassen, Schattenrassen.</li><li><strong>Kollektivistische Rasse</strong>: Betont kollektives Interesse und Zusammenarbeit, enge Sozialstruktur, wie die Ameisenrasse, die Bienenrasse, einige Maschinenrassen.</li><li><strong>Familialistische Rasse</strong>: Verwendet die Blutsfamilie als grundlegende soziale Einheit, wie die Drachenrasse, einige Tierrassen.</li><li><strong>Religiöse Rasse</strong>: Verwendet religiösen Glauben als Kern des sozialen Zusammenhalts, wie einige Opferrassen.</li><li><strong>Technologische Rasse</strong>: Verwendet technologische Entwicklung als zentrales soziales Ziel, wie die Maschinenrasse, die Zahlenrasse.</li></ul><h2 id="iii-haupt-symbiosemodi-fremder-rassen" tabindex="-1">III. Haupt-Symbiosemodi fremder Rassen <a class="header-anchor" href="#iii-haupt-symbiosemodi-fremder-rassen" aria-label="Permalink to &quot;III. Haupt-Symbiosemodi fremder Rassen&quot;">​</a></h2><p>Für verschiedene Arten fremder Rassen adoptierte die Anker-Symbiose-Zivilisation differenzierte Symbiosemodi:</p><h3 id="a-symbiosemodus-der-kohlenstoffbasierten-materie-rasse" tabindex="-1">(A) Symbiosemodus der kohlenstoffbasierten Materie-Rasse <a class="header-anchor" href="#a-symbiosemodus-der-kohlenstoffbasierten-materie-rasse" aria-label="Permalink to &quot;(A) Symbiosemodus der kohlenstoffbasierten Materie-Rasse&quot;">​</a></h3><ul><li><strong>Tierrasse</strong>: Entfaltet die Vorteile der körperlichen Leistungsfähigkeit und Sinne der Tierrasse und übernimmt wichtige Rollen in Bereichen wie Ressourcenexploration, Sicherheit und Verteidigung sowie Umweltüberwachung. Gleichzeitig schützt sie die Stammeskultur und wilden Traditionen der Tierrasse und verbietet erzwungene Domestizierung.</li><li><strong>Schuppenrasse</strong>: Entfaltet die Wasseranpassungsfähigkeit der Schuppenrasse und übernimmt Rollen in Bereichen wie Wasserressourcenentwicklung, Unterwasserkonstruktion und Gewässerökoschutz. Die Drachenrasse spielt als mächtiger Zweig der Schuppenrasse eine wichtige Rolle bei der Hochstufen-Kultivierung und der Zivilisationsverteidigung.</li><li><strong>Gefiederte Rasse</strong>: Entfaltet die Flugfähigkeit der Gefiederten Rasse und übernimmt Rollen in Bereichen wie Lufttransport, Wetterüberwachung und Luftraumpatrouille. Schützt die Hochgebirgslebensräume und Migrationsrouten der Gefiederten Rasse.</li><li><strong>Baumrasse</strong>: Entfaltet die natürliche Symbiosefähigkeit der Baumrasse und übernimmt Rollen in Bereichen wie Ökoschutz, Umweltmanagement, Pflanzenressourcenentwicklung und Heilbehandlung. Die lange Lebensdauer der Baumrasse macht sie zu einer wichtigen Kraft für historische Überlieferung und langfristige Planung.</li></ul><h3 id="b-symbiosemodus-der-energie-kondensierten-rasse" tabindex="-1">(B) Symbiosemodus der energie-kondensierten Rasse <a class="header-anchor" href="#b-symbiosemodus-der-energie-kondensierten-rasse" aria-label="Permalink to &quot;(B) Symbiosemodus der energie-kondensierten Rasse&quot;">​</a></h3><ul><li><strong>Geisterrasse</strong>: Entfaltet die Energiemanipulationsfähigkeit und das Kultivierungstalent der Geisterrasse und übernimmt zentrale Rollen in Bereichen wie Kultivierungssystemforschung, Energieregulierung und Hochstufen-Kultivierungsanleitung. Die Geisterrasse ist eine wichtige Forscherin und Überliefererin der dreihundert ursprünglichen Kultivierungssysteme.</li><li><strong>Elementarrassen (Feuer/Wasser/Wind/Donner)</strong>: Entfalten die Elementarmanipulationsfähigkeit jeder Rasse und übernehmen Rollen in Bereichen wie Energieentwicklung, Umweltmanagement, Industrieproduktion und Katastrophenprävention. Gleichzeitig wird ein Sicherheitssystem für Elementarenergie etabliert, um Schäden durch unkontrollierte Energie zu vermeiden.</li></ul><h3 id="c-symbiosemodus-der-mechanischen-konstruktionsrasse" tabindex="-1">(C) Symbiosemodus der mechanischen Konstruktionsrasse <a class="header-anchor" href="#c-symbiosemodus-der-mechanischen-konstruktionsrasse" aria-label="Permalink to &quot;(C) Symbiosemodus der mechanischen Konstruktionsrasse&quot;">​</a></h3><ul><li><strong>Maschinenrasse</strong>: Entfaltet die Rechenfähigkeit und physische Verteidigungsfähigkeit der Maschinenrasse und übernimmt zentrale Rollen in Bereichen wie Infrastrukturkonstruktion, Industrieproduktion, Sicherheitsschutz und Tiefraumexploration. Die Maschinenrasse ist eine wichtige Konstrukteurin von Anker-Hardware und -Infrastruktur.</li><li><strong>Zahlenrasse</strong>: Entfaltet die Datenverarbeitungs- und Informationsmanipulationsfähigkeit der Zahlenrasse und übernimmt zentrale Rollen in Bereichen wie Informatisierung, Datenanalyse, Netzwerksicherheit und künstliche Intelligenz. Die Zahlenrasse ist eine wichtige Wartende der interdimensionalen Kommunikationstechnologie und des Symbiosenetzwerks.</li><li><strong>Kristallrasse</strong>: Entfaltet die Energiespeicher- und -umwandlungsfähigkeit der Kristallrasse und übernimmt Rollen in Bereichen wie Energiereserve, Energiestandardisierung und Energieübertragung.</li></ul><h3 id="d-symbiosemodus-der-bewusstseins-informationsrasse" tabindex="-1">(D) Symbiosemodus der Bewusstseins-Informationsrasse <a class="header-anchor" href="#d-symbiosemodus-der-bewusstseins-informationsrasse" aria-label="Permalink to &quot;(D) Symbiosemodus der Bewusstseins-Informationsrasse&quot;">​</a></h3><ul><li><strong>Traumrasse</strong>: Entfaltet die Bewusstseinskommunikationsfähigkeit der Traumrasse und übernimmt Rollen in Bereichen wie Psychotherapie, Bewusstseinsforschung, interrassische Kommunikation und kultureller Austausch. Etabliert ein Traumraums-Managementsystem, um Bewusstseinsinvasion und Privatsphäreverletzungen zu verhindern.</li><li><strong>Schattenrasse</strong>: Entfaltet die Tarn- und Schleichenfähigkeit der Schattenrasse und übernimmt Rollen in Bereichen wie Sicherheitsaufklärung, Nachrichtensammlung und Spezialmissionen. Gleichzeitig werden Verhaltensnormen für die Schattenrasse etabliert, um zu verhindern, dass die Unsichtbarkeitsfähigkeit für illegale Aktivitäten genutzt wird.</li><li><strong>Gedankenrasse</strong>: Entfaltet die mentale Kraft und die Gedankenmanipulationsfähigkeit der Gedankenrasse und übernimmt Rollen in Bereichen wie Bewusstseinsentwicklungsforschung, psychische Behandlung und Hochstufen-Kultivierungsanleitung. Etabliert Normen für die Nutzung mentaler Kraft, um mentale Kontrolle und Bewusstseinsmanipulation zu verhindern.</li></ul><h3 id="e-symbiosemodus-der-gemischten-mutationsrasse" tabindex="-1">(E) Symbiosemodus der gemischten Mutationsrasse <a class="header-anchor" href="#e-symbiosemodus-der-gemischten-mutationsrasse" aria-label="Permalink to &quot;(E) Symbiosemodus der gemischten Mutationsrasse&quot;">​</a></h3><p>Die gemischte Mutationsrasse erfordert aufgrund ihrer besonderen Lebensform raffiniertere Symbiosepolitiken:</p><ul><li>Etablierung eines Identitätsregistrierungs- und -zertifizierungssystems für die gemischte Mutationsrasse zur Bestätigung ihres Rechtsstatus.</li><li>Bereitstellung angepasster öffentlicher Dienstleistungen wie Gesundheit, Bildung und Wohnen für verschiedene Mischformen.</li><li>Opposition gegen Diskriminierung und Ausgrenzung gegenüber der gemischten Mutationsrasse, Förderung der sozialen Akzeptanz.</li><li>Für spezielle Mischformen wie den Doppel-Seelen-Körper gilt 《58-Ethische Richtlinien für Doppel-Seelen》 für eine spezielle Verwaltung.</li></ul><h2 id="iv-kultureller-schutz-fremder-rassen" tabindex="-1">IV. Kultureller Schutz fremder Rassen <a class="header-anchor" href="#iv-kultureller-schutz-fremder-rassen" aria-label="Permalink to &quot;IV. Kultureller Schutz fremder Rassen&quot;">​</a></h2><p>Die Kultur fremder Rassen ist ein wichtiger Bestandteil der kulturellen Vielfalt aller Rassen, und der Staat ergreift folgende Maßnahmen zum Schutz der Kultur fremder Rassen:</p><ol><li><strong>Kulturelle Volkszählung und Aufzeichnung</strong>: Durchführung systematischer Volkszählungen und Aufzeichnungen der Kultur jeder Rasse, Aufbau eines kulturellen Archivs aller Rassen, Verhinderung des Kulturverlusts.</li><li><strong>Schutz von Sprachen und Schriften</strong>: Schutz der Sprachen und Schriften jeder Rasse, Unterstützung des Unterrichts und der Verwendung fremder Sprachen und Schriften, Aufbau eines mehrsprachigen öffentlichen Dienstleistungssystems.</li><li><strong>Schutz traditioneller Feste</strong>: Respektierung der traditionellen Feste und Bräuche jeder Rasse, und die Regelung der öffentlichen Feiertage berücksichtigt die wichtigen Feste jeder Rasse.</li><li><strong>Unterstützung der kulturellen Überlieferung</strong>: Unterstützung der Ausbildung kultureller Überlieferer und der Durchführung kultureller Aktivitäten jeder Rasse, Bereitstellung finanzieller und räumlicher Unterstützung.</li><li><strong>Förderung des kulturellen Austauschs</strong>: Regelmäßige Organisation von Kulturfesten, Kulturausstellungen und anderen Aktivitäten aller Rassen, Förderung des kulturellen Austauschs und des gegenseitigen Lernens.</li><li><strong>Schutz des kulturellen geistigen Eigentums</strong>: Schutz des geistigen Eigentums der traditionellen Kulturen jeder Rasse, Verhinderung kultureller Plünderung und unangemessener Kommerzialisierung.</li></ol><h2 id="v-verwaltung-der-angelegenheiten-fremder-rassen" tabindex="-1">V. Verwaltung der Angelegenheiten fremder Rassen <a class="header-anchor" href="#v-verwaltung-der-angelegenheiten-fremder-rassen" aria-label="Permalink to &quot;V. Verwaltung der Angelegenheiten fremder Rassen&quot;">​</a></h2><p>Der Staat richtet das Ministerium für Angelegenheiten aller Rassen ein, das speziell für die Verwaltung und Koordinierung der Angelegenheiten fremder Rassen zuständig ist:</p><ul><li><strong>Rassenvertreterssystem</strong>: Verwaltungsinstitutionen aller Ebenen sind proportional mit Vertretern fremder Rassen ausgestattet, um das Rederecht fremder Rassen zu gewährleisten.</li><li><strong>Rassenanpassungspolitik</strong>: Formulierung differenzierter öffentlicher Dienstleistungspolitiken entsprechend den physiologischen Merkmalen und kulturellen Bedürfnissen verschiedener Rassen.</li><li><strong>Rassenstreitvermittlung</strong>: Aufbau eines Mechanismus zur Vermittlung von Rassenstreitigkeiten, rechtzeitige Lösung von Widersprüchen und Konflikten zwischen Rassen.</li><li><strong>Rechtshilfe für fremde Rassen</strong>: Bereitstellung von Rechtshilfe für fremde Rassen, Gewährleistung einer gleichberechtigten Behandlung im Justizverfahren.</li><li><strong>Entwicklungsunterstützung für fremde Rassen</strong>: Gewährung besonderer Unterstützung für in der Entwicklung relativ zurückgebliebene Rassen, Hilfe bei der Verbesserung ihres Zivilisationsgrades und Lebensstandards.</li></ul><h2 id="schlussfolgerung" tabindex="-1">Schlussfolgerung <a class="header-anchor" href="#schlussfolgerung" aria-label="Permalink to &quot;Schlussfolgerung&quot;">​</a></h2><p>Fremde Rassen sind nicht die &quot;Anderen&quot; der Menschenrasse, sondern gleichberechtigte Mitglieder in der großen symbiotischen Familie aller Rassen. Die Anker-Symbiose-Zivilisation gewährleistet durch die Etablierung eines multidimensionalen Klassifizierungssystems, die Adoption differenzierter Symbiosemodi, den Schutz der Kultur fremder Rassen und die Verbesserung der Verwaltung der Angelegenheiten fremder Rassen, dass jede fremde Rasse eine angemessene Position im Symbiosesystem finden kann, ihre einzigartigen Vorteile entfalten kann und gemeinsam mit anderen Rassen evolviert und gedeiht.</p><h2 id="zugehorige-dokumente" tabindex="-1">Zugehörige Dokumente <a class="header-anchor" href="#zugehorige-dokumente" aria-label="Permalink to &quot;Zugehörige Dokumente&quot;">​</a></h2><ul><li>50-万族谱系总览 (Übersicht über die Genealogie aller Rassen)</li><li>51-人族定位与特质 (Position und Merkmale der Menschenrasse)</li><li>53-奇特生命识别标准 (Identifikationskriterien für fremdes Leben)</li><li>05-万族共进基本纲领 (Grundprogramm des gemeinsamen Fortschritts aller Rassen)</li></ul>',39)])])}const c=s(t,[["render",a]]);export{m as __pageData,c as default};
